INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('bdf97817-250e-4e91-b8a6-0817621003d6', 'f0f35259-85b3-44fa-99c1-4f9ec87c9f4d', 6, 'A paciência com o processo', NULL, '{"intro": "A impaci\u00eancia \u00e9 a voz da pressa, e a cura exige tempo.", "prayer": "Respire profundamente 5 vezes, aceitando o seu tempo.", "practice": "Observe o seu ritmo hoje, sem querer for\u00e7ar nada.", "reflection": "A cura \u00e9 uma espiral, n\u00e3o uma linha reta.", "journal_prompt": "Por que voc\u00ea tem tanta pressa em ser perfeito?"}'), ('71feb284-a2c1-4cb8-a060-d7aba375b100', 'f0f35259-85b3-44fa-99c1-4f9ec87c9f4d', 7, 'O início da vida', NULL, '{"intro": "Agora que a ferida n\u00e3o te define, a vida pode florescer.", "prayer": "Agrade\u00e7a pela sua pr\u00f3pria exist\u00eancia.", "practice": "Planeje um pequeno gesto de cuidado com voc\u00ea mesmo.", "reflection": "Curar \u00e9, finalmente, come\u00e7ar a viver.", "journal_prompt": "Qual \u00e9 o primeiro passo da sua vida renovada?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;